   103 +            public byte[] concatenatedRSToASN1DER(byte[] signature, int signLength) throws IOException {
   104 +                int len = signLength / 2;
   105 +                int arraySize = len + 1;
   106 +
   107 +                byte[] r = new byte[arraySize];
   108 +                byte[] s = new byte[arraySize];
   109 +                System.arraycopy(signature, 0, r, 1, len);
   110 +                System.arraycopy(signature, len, s, 1, len);
   111 +                BigInteger rBigInteger = new BigInteger(r);
   112 +                BigInteger sBigInteger = new BigInteger(s);
   113 +
   114 +                ASN1Encoder.create().write(rBigInteger);
   115 +                ASN1Encoder.create().write(sBigInteger);
   116 +
   117 +                return ASN1Encoder.create()
   118 +                        .writeDerSeq(
   119 +                                ASN1Encoder.create().write(rBigInteger),
   120 +                                ASN1Encoder.create().write(sBigInteger))
   121 +                        .toByteArray();
