   125 +            public byte[] asn1derToConcatenatedRS(byte[] derEncodedSignatureValue, int signLength) throws IOException {
   126 +                int len = signLength / 2;
   127 +
   128 +                List<byte[]> seq = ASN1Decoder.create(derEncodedSignatureValue).readSequence();
   129 +                if (seq.size() != 2) {
   130 +                    throw new IOException("Invalid sequence with size different to 2");
   131 +                }
   132 +
   133 +                BigInteger rBigInteger = ASN1Decoder.create(seq.get(0)).readInteger();
   134 +                BigInteger sBigInteger = ASN1Decoder.create(seq.get(1)).readInteger();
